    subtema: `Exercita-te na piedade, pois ela é proveitosa para tudo`,
    tema: `O Bom Servo de Cristo Jesus`,
    tipo: 'devocional',
    perguntaGancho: `Se Deus estivesse aplicando pessoalmente este texto à vida de vocês, o que ele diria?`,
    reflexaoTexto: `As cartas a Timóteo são o testamento pastoral de Paulo a um jovem líder. A sã doutrina, a piedade pessoal e a fidelidade ao chamado são os temas centrais. Como casal, reconheçam que a saúde da família depende da saúde espiritual de cada um.`,
    perguntaGeradora: `Como 1 Timóteo 4 ilumina algo que vocês estão vivendo juntos no casamento?`,
    reflexaoHomem: `Como marido, Paulo exorta Timóteo a fugir das concupiscências juvenis e seguir a justiça, fé, amor e paz. Quais hábitos espirituais você tem cultivado para ser um homem de Deus maduro?`,
    reflexaoMulher: `Como esposa, Paulo valoriza mulheres que ensinam o bem e instruem as mais novas na piedade. Você tem sido mentora de fé para alguém?`,
    reflexaoFilhos: `Filhos, Paulo diz que a Escritura nos ensina e corrige para nos tornar sábios. Você está lendo a Bíblia regularmente?`,
