    oracaoAlianca: `Senhor, obrigado por tua Palavra que nos alimenta e nos guia. Que 1 Timóteo 4 viva em nossos corações e transforme nossa aliança para a tua glória. Em nome de Jesus, amém.`,
    leituraComplementar: `Salmos 119.105`,
