    estacao: `Outono da Aliança`,
    leitura: `Aplicação da Semana 39`,
    subtema: `Vivendo o texto na aliança`,
    tema: `Da Leitura à Obediência`,
    tipo: 'aplicacao',
    perguntaGeradora: `Como este texto muda a forma como vocês oram um pelo outro?`,
    compromissoPratico: `Esta semana escolham um ensinamento das leituras da semana 39 e apliquem juntos: dividam a tarefa, oração na segunda e avaliação no sábado seguinte.`,
